window.LAB_REACTIONS_DATA = [{"id": "rxn-kola-boiling-concentration", "title": "Kola'nın Kaynatılması ve Karamel Şurubu Dönüşümü", "trigger_op": "HEAT", "required_substances": ["sub-kola"], "min_temp_c": 98.0, "min_time_min": 15, "description": "100°C civarında ısıtılan kola içerisindeki çözünmüş karbonik asit (H2CO3) hemen CO2 gazına bozunarak uçar. Zamanla su (%89) buharlaşır (H2O ^). Geriye koyu renkli, yoğun kıvamlı, sukroz-fruktoz ve konsantre fosforik asit içeren yapışkan bir karamel şurubu kalır.", "products_formed": [{"name": "Konsantre Karamelize Şeker Şurubu & Fosforik Asit Kalıntısı", "formula": "Konsantre: C12H22O11 + H3PO4 + Karamel Kömürü", "phase": "viscous_liquid", "yield_pct": 11.0, "color_hex": "#1a0802"}], "gases_evolved": ["Su Buharı (H2O ^)", "Karbondioksit Gazı (CO2 ^)"], "temp_change_c": 0, "ph_change": -0.5, "safety_warning": "Sıcak şeker şurubu deriye yapışırsa ciddi termal yanıklara yol açabilir.", "alchemical_note": "Ayrıştırma (Separatio): Uçucu su (Mercurius) bedeni terk eder, geriye yoğun tuz ve kükürt içeren kara öz kalır."}, {"id": "rxn-potassium-with-acidic-caramel-or-water", "title": "Potasyum Metalinin Asidik Karamel veya Su ile Patlamalı Reaksiyonu", "trigger_op": "MIX", "required_substances": ["sub-potasyum", "sub-kola"], "condition_note": "Konsantre kola kalıntısına veya kolaya potasyum metali atılıp çalkalandığında", "description": "Potasyum (K) metalik yapısı gereği su molekülleri ve fosforik asidin protonları (H+) ile anında şiddetli ekzotermik reaksiyona girer: 2K + 2H2O -> 2KOH + H2 ^ + Isı ve 3K + H3PO4 -> K3PO4 + 1.5H2 ^. Açığa çıkan muazzam ısı (Delta H = -392 kJ/mol) hidrojen gazını tutuşturarak morumsu alevler ve patlamalar yaratır. Aşırı ısı ortamdaki karamel şekerini anında kalsine ederek kapkara gözenekli karbon köpüğüne dönüştürür!", "products_formed": [{"name": "Kömürleşmiş Karbon Köpüğü & Potasyum Fosfat Tuzu", "formula": "C (Kömür) + K3PO4 + KOH", "phase": "solid", "yield_pct": 85.0, "color_hex": "#09090b"}], "gases_evolved": ["Hidrojen Gazı (H2 ^ - Alevli Yanıcı)", "Karbondioksit & Su Dumanı"], "temp_change_c": 180, "ph_change": 8.0, "safety_warning": "ŞİDDETLİ PATLAMA VE TUTUŞMA TEHLİKESİ! Hidrojen gazı kendiliğinden alev alır. Göz ve yüz koruması şarttır.", "alchemical_note": "Ateş ile Suyun Çatışması (Coniunctio Violenta): Metalik aktif kükürt (Potasyum) nemi yakar, Nigredo (simsiyah kül) fazı doğar."}, {"id": "rxn-potassium-water-pure", "title": "Potasyum Metalinin Su ile Şiddetli Tepkimesi", "trigger_op": "MIX", "required_substances": ["sub-potasyum", "sub-saf-su"], "description": "2K + 2H2O -> 2KOH + H2 ^. Potasyum su üzerinde hızla dönerek erir ve mor bir alevle tutuşur. Çözelti güçlü bazik Potasyum Hidroksite (pH 14) dönüşür.", "products_formed": [{"name": "Potasyum Hidroksit Çözeltisi", "formula": "KOH(aq)", "phase": "liquid", "yield_pct": 98.0, "color_hex": "#f8fafc"}], "gases_evolved": ["Hidrojen Gazı (H2 ^)"], "temp_change_c": 75, "ph_change": 7.0, "safety_warning": "Patlama ve kostik sıçrama tehlikesi!", "alchemical_note": "Metalik canlılığın suda açığa çıkması."}, {"id": "rxn-bleach-acid-chlorine-gas", "title": "Çamaşır Suyu ve Asit Reaksiyonu (Ölümcül Klor Gazı Salınımı)", "trigger_op": "MIX", "required_substances": ["sub-camasir-suyu", "sub-tuz-ruhu"], "description": "NaOCl + 2HCl -> NaCl + H2O + Cl2 ^. Çamaşır suyu hidroklorik asit ile birleştiğinde anında boğucu, yeşilimsi sarı renkli, ölümcül KLOR GAZI açığa çıkar.", "products_formed": [{"name": "Sofra Tuzu ve Su Çözeltisi", "formula": "NaCl + H2O", "phase": "liquid", "yield_pct": 90.0, "color_hex": "#fef9c3"}], "gases_evolved": ["ÖLÜMCÜL KLOR GAZI (Cl2 ^)"], "temp_change_c": 15, "ph_change": -8.0, "safety_warning": "ÖLÜMCÜL ZEHİRLİ GAZ TEHLİKESİ! Asla ev veya kapalı laboratuvar ortamında karıştırılmamalıdır.", "alchemical_note": "Toksik Ejderhanın Uyanışı."}, {"id": "rxn-vinegar-bicarbonate-volcano", "title": "Sirke ve Karbonat Reaksiyonu (Karbondioksit Köpürmesi)", "trigger_op": "MIX", "required_substances": ["sub-sirke", "sub-karbonat"], "description": "CH3COOH + NaHCO3 -> CH3COONa + H2O + CO2 ^. Asetik asit sodyum bikarbonatı nötralize ederek şiddetli köpürmeyle bol miktarda karbondioksit gazı üretir. Çözeltide sodyum asetat tuzu kalır.", "products_formed": [{"name": "Sodyum Asetat Çözeltisi (Sıcak Buz Öncülü)", "formula": "CH3COONa + H2O", "phase": "liquid", "yield_pct": 95.0, "color_hex": "#f8fafc"}], "gases_evolved": ["Karbondioksit Gazı (CO2 ^ - Yoğun Köpük)"], "temp_change_c": -4, "ph_change": 4.5, "safety_warning": "Taşma ve köpürme riski.", "alchemical_note": "Ruhun bedeni terk ederek yükselmesi (Sublimatio)."}, {"id": "rxn-saponification-oil-ash", "title": "Zeytinyağı ve Kül ile Antik Kastil Sabunlaşması", "trigger_op": "MIX", "required_substances": ["sub-zeytinyagi", "sub-odun-kulu"], "min_temp_c": 60.0, "min_time_min": 30, "description": "Zeytinyağındaki trigliseritler odun külünden süzülen alkali potasyum karbonat (K2CO3 / KOH) varlığında hidrolize uğrar. Gliserin molekülleri ayrılır ve yağ asitleri potasyum tuzu haline gelerek doğal yumuşak sabun (Arap sabunu) oluşturur.", "products_formed": [{"name": "Antik Doğal Potas Sabunu", "formula": "C17H33COOK (Potasyum Oleat)", "phase": "solid", "yield_pct": 82.0, "color_hex": "#a3e635"}, {"name": "Doğal Gliserin Çözeltisi", "formula": "C3H8O3", "phase": "liquid", "yield_pct": 18.0, "color_hex": "#f1f5f9"}], "gases_evolved": [], "temp_change_c": 10, "ph_change": 2.5, "safety_warning": "Sıcak alkali karışım cilde temas etmemelidir.", "alchemical_association": "Sal Saponis / Arınma Taşı"}, {"id": "rxn-aqua-regia-gold-solution", "title": "Kral Suyu (Aqua Regia) ile Altın Çözündürme", "trigger_op": "MIX", "required_substances": ["sub-tuz-ruhu", "sub-kezzap", "sub-altin"], "description": "3HCl + HNO3 -> NOCl + Cl2 + 2H2O. Oluşan nitrozil klorür ve serbest klor, soy metal altını (Au) oksitleyerek sarı-turuncu renkli Kloroaurik Aside [HAuCl4] dönüştürür. Altın tamamen sıvı faza geçer.", "products_formed": [{"name": "Kloroaurik Asit (Sıvı Altın Çözeltisi)", "formula": "HAuCl4(aq)", "phase": "liquid", "yield_pct": 99.0, "color_hex": "#f59e0b"}], "gases_evolved": ["Nitrozil Klorür Gazı (NOCl ^)", "Klor Gazı (Cl2 ^)"], "temp_change_c": 25, "ph_change": 0.0, "safety_warning": "Aşırı derecede korozif ve zehirli dumanlar çıkarır. Çeker ocak altında yapılmalıdır.", "alchemical_note": "Altın Kralın Çözünüşü (Solutio Regis)."}, {"id": "rxn-spagyric-calcination-ash", "title": "Bitkisel Posanın Kalsinasyonu ve Saf Kristal Tuz Eldesi", "trigger_op": "CALCINE", "required_substances": ["sub-biberiye"], "min_temp_c": 500.0, "min_time_min": 60, "description": "Biberiye bitkisi 500-600°C fırında kalsine edilir. Tüm organik karbon (selüloz, klorofil) yanarak CO2 ve suya uçar. Geriye potasyum karbonat ve minerallerden oluşan bembeyaz 'Sal' (Bitki Tuzu) kristali kalır.", "products_formed": [{"name": "Kalsine Saf Bitki Tuzu (Sal Vegetabilis)", "formula": "K2CO3 + Mineral Sal", "phase": "solid", "yield_pct": 4.5, "color_hex": "#f8fafc"}], "gases_evolved": ["Karbondioksit (CO2 ^)", "Su Buharı (H2O ^)"], "temp_change_c": 0, "ph_change": 4.0, "safety_warning": "Yüksek fırın sıcaklığı. Yanık riski.", "alchemical_note": "Spajirik Kalsinasyon: Bedensel küllerin arıtılarak ölümsüz tuza (Sal) dönüşmesi."}, {"id": "rxn-milk-curdling-casein", "title": "Sütün Asit ile Pıhtılaşması (Doğal Kazein Çökeltisi)", "trigger_op": "MIX", "required_substances": ["sub-sut", "sub-sirke"], "description": "Süte asetik asit (sirke) eklendiğinde pH 4.6 (kazeinin izoelektrik noktası) seviyesine düşer. Negatif yükünü kaybeden kazein miselleri birbirine yapışarak beyaz pıhtılar halinde çöker. Üstte şeffaf sarı peyniraltı suyu (whey) kalır.", "products_formed": [{"name": "Kazein Çökeltisi (Doğal Biyoplastik / Peynir)", "formula": "Kazein Protein Kütlesi", "phase": "solid", "yield_pct": 14.0, "color_hex": "#fef08a"}, {"name": "Peyniraltı Suyu (Laktoz ve Mineraller)", "formula": "Serum Lactis", "phase": "liquid", "yield_pct": 86.0, "color_hex": "#fef9c3"}], "gases_evolved": [], "temp_change_c": 0, "ph_change": -2.0, "safety_warning": "Güvenli biyokimyasal çökelme.", "alchemical_note": "Sütün Koagülasyonu (Pıhtılaşma Fazı)."}, {"id": "rxn-silver-tarnish-cleaning", "title": "Gümüşün Karbonat ve Sıcak Su ile İndirgenerek Temizlenmesi", "trigger_op": "HEAT", "required_substances": ["sub-gumus", "sub-karbonat", "sub-saf-su"], "min_temp_c": 90.0, "min_time_min": 10, "description": "Kararmış gümüş (Ag2S), alüminyum folyo ve karbonatlı sıcak su içinde elektrokimyasal redoksla temas ettirildiğinde kükürt alüminyuma transfer olur ve gümüş parıldayan saf beyaz metalik haline döner.", "products_formed": [{"name": "Saflaştırılmış Parlak Gümüş", "formula": "Ag", "phase": "solid", "yield_pct": 99.8, "color_hex": "#f8fafc"}], "gases_evolved": ["Eser Hidrojen Sülfür Koku İzi"], "temp_change_c": 0, "ph_change": 0.0, "safety_warning": "Sıcak su yanığına dikkat.", "alchemical_note": "Luna'nın Kararmış Nigredo'dan Albedo'ya Dönüşü."}, {"id": "rxn-cola-milk-separation", "title": "Kola ve Süt Karışımı (Fosforik Asit Pıhtılaşması)", "trigger_op": "MIX", "required_substances": ["sub-kola", "sub-sut"], "description": "Kola içindeki fosforik asit (H3PO4) sütün pH'ını anında kazein proteininin çökme noktasına (pH 4.6) düşürür. Kazein, kolanın karamel pigmentlerini de içerisine hapsederek koyu renkli ağır pıhtılar halinde dibe çöker. Üst kısımda berrak, şeffaf asidik peyniraltı sıvısı kalır.", "products_formed": [{"name": "Karamel-Kazein Ağır Pıhtı Çökeltisi", "formula": "Kazein + Fosfat + Karamel", "phase": "solid", "yield_pct": 25.0, "color_hex": "#451a03"}, {"name": "Berraklaşmış Asidik Sıvı Faz", "formula": "H2O + Şekerler + Eser Fosfat", "phase": "liquid", "yield_pct": 75.0, "color_hex": "#fef08a"}], "gases_evolved": ["Eser Karbondioksit (CO2 ^)"], "temp_change_c": 0, "ph_change": 1.2, "safety_warning": "Zararsızdır; pıhtılaşmış kütle süzülerek ayrılabilir.", "alchemical_note": "Ayrışma (Separatio): Sütün beyaz kazeini kolanın karanlığını yutar ve dibe çöker."}, {"id": "rxn-quicklime-water", "title": "Sönmemiş Kirecin Su ile Söndürülmesi (Şiddetli Isı Salınımı)", "trigger_op": "MIX", "required_substances": ["sub-sonmemis-kirec", "sub-saf-su"], "description": "CaO + H2O -> Ca(OH)2. Kalsiyum oksit su ile temas ettiğinde suyu kaynatacak kadar yüksek ekzotermik ısı yayar (Delta H = -63.7 kJ/mol). Karışım yoğun su buharı çıkararak kabarır ve beyaz Sönmüş Kireç (Kalsiyum Hidroksit) pastasına dönüşür.", "products_formed": [{"name": "Sönmüş Kireç Pastası (Kalsiyum Hidroksit)", "formula": "Ca(OH)2", "phase": "solid", "yield_pct": 98.0, "color_hex": "#f8fafc"}], "gases_evolved": ["Yoğun Kaynar Su Buharı (H2O ^)"], "temp_change_c": 85, "ph_change": 5.8, "safety_warning": "KAYNAMA VE SIÇRAMA TEHLİKESİ! Isı 100°C'yi aşabilir, kostik sıçrama göze zarar verir.", "alchemical_note": "Sönmeyen Ateşin Canlanması (Ignis Gehennae)."}, {"id": "rxn-iron-tannin-ink", "title": "Demir ve Tanen ile Tarihsel Kalıcı Siyah Mürekkep Eldesi", "trigger_op": "MIX", "required_substances": ["sub-kara-zac", "sub-cay"], "description": "Çaydaki veya meşe mazısındaki gallotanik asitler demir(II) sülfat ile şelasyon reaksiyonuna girer. Havadaki oksijenle hızla oksitlenerek suda çözünmeyen, yüzyıllarca solmayan simsiyah Ferri-Tannat mürekkebine (Iron Gall Ink) dönüşür.", "products_formed": [{"name": "Tarihsel Kalıcı Siyah Demir Mürekkebi", "formula": "Demir(III) Tannat Kompleksi", "phase": "liquid", "yield_pct": 96.0, "color_hex": "#09090b"}], "gases_evolved": [], "temp_change_c": 0, "ph_change": -0.8, "safety_warning": "Kumaş ve ahşapta kalıcı siyah leke bırakır.", "alchemical_note": "Nigredo Tektürü: Yeşil aslanın (FeSO4) bitkisel tanenle evliliği kalıcı siyahı doğurur."}, {"id": "rxn-iodine-starch-indicator", "title": "İyot ve Nişasta ile Koyu Lacivert Kompleks Dönüşümü", "trigger_op": "MIX", "required_substances": ["sub-iyot", "sub-nisasta"], "description": "İyot molekülleri (I3-) mısır nişastasının amiloz sarmal yapısının merkezine kayarak hapsolur. Işık absorpsiyon spektrumu anında değişir ve karışım derin gece mavisi / mor-lacivert bir renge dönüşür. Karışım ısıtıldığında (60°C) sarmal açılır ve renk kaybolur; soğuyunca tekrar döner!", "products_formed": [{"name": "Derin Lacivert Amiloz-İyot Kompleksi", "formula": "Amiloz-[I5]-", "phase": "liquid", "yield_pct": 99.0, "color_hex": "#1e1b4b"}], "gases_evolved": [], "temp_change_c": 0, "ph_change": 0.0, "safety_warning": "Zararsız renk indikatörü tepkimesi.", "alchemical_note": "Görünmeyenin Mor İplikle Tezahürü."}, {"id": "rxn-fermentation-sugar-yeast", "title": "Maya ile Şekerin Alkol ve Karbondioksite Fermantasyonu", "trigger_op": "HEAT", "required_substances": ["sub-seker", "sub-maya", "sub-saf-su"], "min_temp_c": 30.0, "min_time_min": 60, "description": "C6H12O6 (Glukoz/Fruktoz) -> 2 C2H5OH (Etanol) + 2 CO2 ^. 30-37°C sıcaklıkta Saccharomyces cerevisiae mayasının zimaz enzimleri sukrozu hidrolize eder ve anaerobik glikolizle etil alkol ve yoğun köpürmeli karbondioksit gazına dönüştürür.", "products_formed": [{"name": "Fermente Alkolik Sıvı (Ham Şarap/Bira Özü %10-14)", "formula": "C2H5OH(aq) + Maya Biyokütlesi", "phase": "liquid", "yield_pct": 48.0, "color_hex": "#fef08a"}], "gases_evolved": ["Karbondioksit Gazı (CO2 ^ - Kesintisiz Baloncuklar)"], "temp_change_c": 3, "ph_change": -1.5, "safety_warning": "Kapalı kapta aşırı gaz basıncı patlamaya yol açabilir, fermantasyon kilidi kullanılmalıdır.", "alchemical_note": "Fermantasyon (Fermentatio): Maddenin canlı ruhla aşılanarak tinsel alkole yükselişi."}, {"id": "rxn-copper-ammonia-schweitzer", "title": "Bakır Sülfat ve Amonyak ile Kraliyet Mavisi Kompleksi", "trigger_op": "MIX", "required_substances": ["sub-goztasi", "sub-amonyak-cozelti"], "description": "CuSO4 + 4 NH3 -> [Cu(NH3)4]SO4. Açık mavi bakır sülfat çözeltisine amonyak damlatıldığında önce açık mavi bakır hidroksit çökeleği oluşur; amonyak fazlasında bu çökelek anında çözünerek göz kamaştırıcı koyu krallık mavisi (Schweitzer Reaktifi) kompleksine dönüşür. Bu çözelti selülozu eritebilir!", "products_formed": [{"name": "Kraliyet Mavisi Tetraaminbakır(II) Çözeltisi (Schweitzer)", "formula": "[Cu(NH3)4]SO4(aq)", "phase": "liquid", "yield_pct": 98.0, "color_hex": "#1d4ed8"}], "gases_evolved": ["Eser Amonyak Buharı (NH3 ^)"], "temp_change_c": 5, "ph_change": 6.0, "safety_warning": "Amonyak buharlarını solumayınız.", "alchemical_note": "Venüs'ün Mavi Mücevhere Dönüşü."}, {"id": "rxn-sea-water-distillation", "title": "Deniz Suyunun Damıtılması (Tatlı Su ve Kristal Tuz Ayrışması)", "trigger_op": "DISTILL", "required_substances": ["sub-deniz-suyu"], "min_temp_c": 100.0, "min_time_min": 30, "description": "Deniz suyu 100°C'de kaynatıldığında saf su buharlaşarak imbikten damıtılır ve içilebilir saf tatlı su (Aqua Dulcis) olarak toplanır. Kazanın dibinde ise sodyum klorür, magnezyum ve kalsiyum minerallerinden oluşan bembeyaz kristal deniz tuzu kalır.", "products_formed": [{"name": "Damıtılmış Saf Tatlı Su (Kondensat)", "formula": "H2O(l)", "phase": "liquid", "yield_pct": 96.5, "color_hex": "#38bdf8"}, {"name": "Kristalize Ham Deniz Tuzu Kalıntısı", "formula": "NaCl + MgCl2 + CaSO4", "phase": "solid", "yield_pct": 3.5, "color_hex": "#f8fafc"}], "gases_evolved": ["Yoğunlaşan Su Buharı (H2O ^)"], "temp_change_c": 0, "ph_change": -1.1, "safety_warning": "Kuru kaynama durumunda tuz kabın dibine yapışabilir.", "alchemical_note": "Tuz ile Suyun Ayrışması (Separatio Maris)."}, {"id": "rxn-copper-nitric-acid-brown-fumes", "title": "Bakırın Kezzapta Çözünmesi ve Kızıl NO2 Dumanı Salınımı", "trigger_op": "MIX", "required_substances": ["sub-bakir", "sub-kezzap"], "description": "Cu + 4 HNO3 -> Cu(NO3)2 + 2 NO2 ^ + 2 H2O. Bakır nitrik aside atıldığında çözelti anında yeşilden zümrüt mavisine dönerken, havadan ağır, yoğun, zehirli kızıl-kahverengi AZOT DİOKSİT (NO2) gazı fışkırır. Aşırı ekzotermiktir.", "products_formed": [{"name": "Bakır(II) Nitrat Mavi Çözeltisi", "formula": "Cu(NO3)2(aq)", "phase": "liquid", "yield_pct": 95.0, "color_hex": "#0ea5e9"}], "gases_evolved": ["TOKSİK KIZIL-KAHVERENGİ AZOT DİOKSİT GAZI (NO2 ^)"], "temp_change_c": 60, "ph_change": 0.5, "safety_warning": "ÖLÜMCÜL AKCİĞER ÖDEMİ RİSKİ! NO2 gazı kesinlikle açık havada veya çeker ocakta üretilmelidir.", "alchemical_note": "Kızıl Ejderhanın Gazabı."}, {"id": "rxn-ammonia-hcl-smoke", "title": "Amonyak ve Tuz Ruhundan Beyaz Salmiak Dumanı", "trigger_op": "MIX", "required_substances": ["sub-amonyak-cozelti", "sub-tuz-ruhu"], "description": "NH3(g) + HCl(g) -> NH4Cl(s). Sıvılar birbirine doğrudan değmese dahi gaz fazında buharları karşılaştığı anda odada yoğun, bembeyaz, sis gibi Amonyum Klorür (Sal Ammoniac / Nişadır) kristalleri havada asılı kalır.", "products_formed": [{"name": "Nişadır Kristal Çökeltisi / Dumanı (Sal Ammoniac)", "formula": "NH4Cl", "phase": "solid", "yield_pct": 98.0, "color_hex": "#f1f5f9"}], "gases_evolved": ["Yoğun Beyaz Duman Sisi (NH4Cl Mikro-Kristalleri)"], "temp_change_c": 20, "ph_change": 0.0, "safety_warning": "Duman solunum yollarını tahriş edebilir.", "alchemical_note": "İki Ruhun Havadaki Dansından Doğan Tuz (Sal Volatile)."}, {"id": "rxn-mercury-gold-amalgam", "title": "Cıva ve Altın Amalgamasyonu", "trigger_op": "MIX", "required_substances": ["sub-civa", "sub-altin"], "description": "Au + x Hg -> AuHgx (Amalgam). Sıvı cıva altın yaprağını veya tozunu anında ıslatarak yapısına çeker. Katı altın cıvanın içinde çözünerek gümüşi renkli, yumuşak macun kıvamında Altın Amalgamı oluşturur. Isıtıldığında cıva uçar (356°C) ve saf sünger altın kalır.", "products_formed": [{"name": "Gümüşi Altın Amalgam Macunu", "formula": "AuHg2 / AuHg3", "phase": "solid", "yield_pct": 100.0, "color_hex": "#e2e8f0"}], "gases_evolved": [], "temp_change_c": 2, "ph_change": 0.0, "safety_warning": "Amalgam ısıtıldığında aşırı zehirli cıva buharı çıkar, imbikte geri kazanılmalıdır.", "alchemical_note": "Kralın Sıvı Cıva Denizinde Dinlenmesi (Rex in Balneo Mercurii)."}];
